mapper.update:
update fe_reference_settlement set status = 'VOID', update_time = now()
where redemption_id = #{redemptionId}
  and (status in ('OPEN', 'DISPUTED') or (supplier_kind = 'AUTHOR' and status = 'SETTLED_OFFLINE'))

mapper.select:
select  from fe_reference_settlement r 
where r.merchant_id = #{merchantId}

    and r.status = #{status}
    and r.status != 'VOID'

order by r.activity_id desc, r.id desc

select  from fe_reference_settlement r
where r.id = #{id} and r.merchant_id = #{merchantId}
for update
